<?php declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN','VERIFICADOR']);?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Resumen financiero — Hache Natación</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f6fa;font-family:Arial,sans-serif;color:#172033}.wrap{max-width:980px;margin:auto;padding:72px 14px 36px}h1{margin:0 0 5px;font-size:28px}.sub{color:#64748b;font-size:13px;margin-bottom:16px}.tabs{display:flex;gap:8px;overflow-x:auto;margin-bottom:16px}.tab{border:0;background:#e2e8f0;color:#334155;padding:10px 14px;border-radius:10px;font-weight:800;white-space:nowrap;cursor:pointer}.tab.active{background:#172033;color:#fff}.panel{display:none}.panel.active{display:block}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.card{background:#fff;border-radius:16px;padding:14px;box-shadow:0 3px 12px #0000000d}.card.big{grid-column:1/-1}.k{font-size:11px;color:#64748b;text-transform:uppercase;font-weight:800;letter-spacing:.05em}.v{font-size:25px;font-weight:900;margin-top:5px}.s{font-size:12px;color:#64748b;margin-top:5px}.section{margin-top:18px}.section h2{font-size:18px;margin:0 0 10px}.row{display:flex;justify-content:space-between;gap:12px;padding:11px 0;border-bottom:1px solid #eef2f7}.row:last-child{border-bottom:0}.row strong{font-size:14px}.row span{font-size:13px;color:#64748b}.empty{padding:20px;text-align:center;color:#64748b}.error{color:#991b1b;font-weight:700}.bar{height:8px;background:#e2e8f0;border-radius:99px;overflow:hidden;margin-top:7px}.fill{height:100%;background:#172033}.history-controls{display:grid;grid-template-columns:1fr 1fr auto;gap:8px;margin-bottom:14px}.field{background:#fff;border:1px solid #cbd5e1;border-radius:12px;padding:9px 10px}.field label{display:block;font-size:10px;color:#64748b;font-weight:800;margin-bottom:4px;text-transform:uppercase}.field input{width:100%;border:0;background:transparent;font-size:15px;padding:0}.load{border:0;border-radius:12px;background:#172033;color:#fff;font-weight:800;padding:0 14px;cursor:pointer}.month-block{margin-bottom:12px}.month-head{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:7px}.month-title{font-weight:900}.month-total{font-size:13px;color:#64748b}.mini-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.mini{background:#fff;border-radius:12px;padding:11px}.mini b{display:block;font-size:18px;margin-top:3px}.mini span{font-size:10px;color:#64748b;text-transform:uppercase;font-weight:800}.history-total{margin-bottom:16px}.split{background:#fff;border-radius:16px;padding:14px}.split-note{font-size:12px;color:#64748b;margin-top:8px;line-height:1.45}@media(max-width:620px){.history-controls{grid-template-columns:1fr 1fr}.load{grid-column:1/-1;padding:11px}.mini-grid{grid-template-columns:1fr 1fr}}@media(min-width:720px){.wrap{padding-top:36px}.grid{grid-template-columns:repeat(4,1fr)}.card.big{grid-column:span 2}}
</style></head><body><main class="wrap"><h1>Resumen financiero</h1><div class="sub">Cobertura mensual, ingresos recibidos y reparto por sede</div><div class="tabs"><button id="tabActual" class="tab active" data-tab="actual"></button><button id="tabSiguiente" class="tab" data-tab="siguiente"></button><button class="tab" data-tab="historial">Historial</button></div><section id="panel-actual" class="panel active"><div id="actual"><div class="empty">Cargando…</div></div></section><section id="panel-siguiente" class="panel"><div id="siguiente"><div class="empty">Cargando…</div></div></section><section id="panel-historial" class="panel"><div class="history-controls"><div class="field"><label>Desde</label><input id="desde" type="month"></div><div class="field"><label>Hasta</label><input id="hasta" type="month"></div><button id="cargarHistorial" class="load" type="button">Ver periodo</button></div><div id="historial"><div class="empty">Selecciona un periodo.</div></div></section></main><script>
const qs=new URLSearchParams(location.search),SEDE=(qs.get('sede')||localStorage.getItem('hache_sede')||'MONTEVERDE').toUpperCase();
const money=n=>Number(n||0).toLocaleString('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0}),meses=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const now=new Date(),actual={anio:now.getFullYear(),mes:now.getMonth()+1},nextDate=new Date(now.getFullYear(),now.getMonth()+1,1),sig={anio:nextDate.getFullYear(),mes:nextDate.getMonth()+1};
const periodValue=x=>x.anio+'-'+String(x.mes).padStart(2,'0'),periodLabel=x=>meses[x.mes-1][0].toUpperCase()+meses[x.mes-1].slice(1)+' '+x.anio;
document.getElementById('tabActual').textContent=periodLabel(actual);document.getElementById('tabSiguiente').textContent=periodLabel(sig);document.getElementById('desde').value=actual.anio+'-01';document.getElementById('hasta').value=periodValue(actual);
function card(k,v,s='',big=false){return `<div class="card ${big?'big':''}"><div class="k">${esc(k)}</div><div class="v">${esc(v)}</div>${s?`<div class="s">${esc(s)}</div>`:''}</div>`}
function splitUI(r){if(!r)return'';const partnerText=r.socio||'Socio',partner=esc(partnerText);return `<section class="section"><h2>Reparto ${partner} · Hache</h2><div class="grid">${card('Para '+partnerText,money(r.total_socio),'Según reglas de la sede',true)}${card('Para Hache',money(r.total_hache))}${card('Base cobrada',money(r.total_cobrado))}</div><div class="split section">${['MENSUALIDAD','INTENSIVO','INSCRIPCION'].map(k=>{const x=r.por_tipo[k];const label={MENSUALIDAD:'Mensualidades',INTENSIVO:'Intensivos',INSCRIPCION:'Inscripciones'}[k];return `<div class="row"><div><strong>${label}</strong><div class="s">${money(x.total)} cobrados</div></div><span>${partner}: ${money(x.socio)} · Hache: ${money(x.hache)}</span></div>`}).join('')}<div class="split-note">Reglas: mensualidad ${Number(r.reglas.mensualidad_socio||0)}% para ${partner}; intensivo ${Number(r.reglas.intensivo_socio||0)}%; inscripción ${Number(r.reglas.inscripcion_socio||0)}%.</div></div></section>`}
function renderMonth(x){const t=x.por_tipo,m=x.mensualidades_periodo,max=Math.max(1,...x.metodos.map(v=>Number(v.total||0)));return `<div class="grid">${card('Mensualidades del periodo',m.alumnos,money(m.total)+' cubiertos',true)}${card('Dinero recibido',money(x.caja.total),x.caja.cantidad+' pagos')}${card('Alumnos con pagos',x.caja.alumnos)}${card('Inscripciones',money(t.INSCRIPCION.total),t.INSCRIPCION.cantidad+' pagos')}${card('Mensualidades cobradas',money(t.MENSUALIDAD.total),t.MENSUALIDAD.cantidad+' pagos')}${card('Cursos intensivos',money(t.INTENSIVO.total),t.INTENSIVO.cantidad+' pagos')}</div>${splitUI(x.reparto)}<section class="section"><h2>Métodos de pago</h2><div class="card">${x.metodos.length?x.metodos.map(v=>{const width=Math.max(4,Math.min(100,Number(v.total)/max*100));return `<div class="row"><div><strong>${esc(String(v.metodo||'').replace('_',' '))}</strong><div class="bar"><div class="fill" style="width:${width}%"></div></div></div><span>${money(v.total)} · ${Number(v.cantidad||0)}</span></div>`}).join(''):'<div class="empty">Sin movimientos.</div>'}</div></section>`}
async function loadSingle(target,p){const el=document.getElementById(target);el.innerHTML='<div class="empty">Cargando…</div>';try{const r=await fetch(`/api/resumen-financiero.php?mes=${p.mes}&anio=${p.anio}&sede=${encodeURIComponent(SEDE)}`),x=await r.json();if(!r.ok||!x.ok)throw new Error(x.error||'No se pudo cargar');el.innerHTML=renderMonth(x)}catch(e){el.innerHTML='<div class="empty error">'+esc(e.message)+'</div>'}}
function monthName(p){return meses[p.mes-1][0].toUpperCase()+meses[p.mes-1].slice(1)+' '+p.anio}
async function loadHistory(){const desde=document.getElementById('desde').value,hasta=document.getElementById('hasta').value,h=document.getElementById('historial');if(!desde||!hasta)return;h.innerHTML='<div class="empty">Cargando historial…</div>';try{const r=await fetch(`/api/resumen-financiero.php?desde=${encodeURIComponent(desde)}&hasta=${encodeURIComponent(hasta)}&sede=${encodeURIComponent(SEDE)}`),x=await r.json();if(!r.ok||!x.ok)throw new Error(x.error||'No se pudo cargar');const totals=x.totales;h.innerHTML=`<div class="grid history-total">${card('Total recibido',money(totals.caja),totals.pagos+' pagos',true)}${card('Socio',money(totals.socio),x.sede?.socio||'')}${card('Hache',money(totals.hache))}${card('Inscripciones',money(totals.inscripciones))}${card('Mensualidades',money(totals.mensualidades))}${card('Intensivos',money(totals.intensivos))}</div>${x.detalle.map(m=>`<section class="month-block"><div class="month-head"><div class="month-title">${esc(monthName(m.periodo))}</div><div class="month-total">${money(m.caja.total)} recibidos</div></div><div class="mini-grid"><div class="mini"><span>Mensualidades periodo</span><b>${Number(m.mensualidades_periodo.alumnos||0)}</b><div class="s">${money(m.mensualidades_periodo.total)}</div></div><div class="mini"><span>Socio</span><b>${money(m.reparto.total_socio)}</b><div class="s">${esc(m.reparto.socio)}</div></div><div class="mini"><span>Hache</span><b>${money(m.reparto.total_hache)}</b></div><div class="mini"><span>Ingresos</span><b>${money(m.caja.total)}</b><div class="s">${Number(m.caja.cantidad||0)} pagos</div></div></div></section>`).join('')}`;}catch(e){h.innerHTML='<div class="empty error">'+esc(e.message)+'</div>'}}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('panel-'+b.dataset.tab).classList.add('active');if(b.dataset.tab==='historial')loadHistory()}));document.getElementById('cargarHistorial').onclick=loadHistory;loadSingle('actual',actual);loadSingle('siguiente',sig);
</script></body></html>
